              "{\"description\":\"The reaction in financial futures was immediate overnight to China's retaliatory action.\",\"headline\":\"Watch how futures markets in stocks, soybeans and the dollar tanked suddenly overnight on the China trade retaliation\",\"dateCreated\":\"2018-04-04T12:01:42+0000\",\"datePublished\":\"2018-04-04T12:01:42+0000\",\"dateModified\":\"2018-04-04T14:05:22+0000\",\"author\":[{\"name\":\"John Melloy\"}],\"publisher\":{\"name\":\"CNBC\",\"foundingDate\":\"1989-04-17\",\"sameAs\":[\"https://www.facebook.com/cnbc\",\"https://www.instagram.com/cnbc\",\"https://www.linkedin.com/company/cnbc\",\"https://twitter.com/cnbc\",\"https://en.wikipedia.org/wiki/CNBC\",\"https://www.youtube.com/cnbc\"]},\"articleSection\":\"Markets\",\"keywords\":[\"cnbc\",\"Articles\",\"Markets\",\"Investment strategy\",\"Stock markets\",\"stocks\",\"Investing\",\"source:tagname:CNBC US Source\"]}"
